import java.util.*;

public class Solution {
    public int maxEnvelopes(int[][] envelopes) {
        Arrays.sort(envelopes, (a, b) -> a[0] == b[0] ? b[1] - a[1] : a[0] - b[0]);
        int[] tails = new int[envelopes.length];
        int sz = 0;
        for (int[] env : envelopes) {
            int h = env[1];
            int l = 0, r = sz;
            while (l < r) {
                int m = l + (r - l) / 2;
                if (tails[m] < h) l = m + 1;
                else r = m;
            }
            tails[l] = h;
            if (l == sz) sz++;
        }
        return sz;
    }
}

